package dev.mineagent.runtime.neoforge.ui;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import dev.mineagent.runtime.neoforge.content.*;import net.minecraft.server.level.ServerPlayer;import java.util.*;import java.util.concurrent.*;
/** Isolated texture input uses the same file library and tool routes as ordinary content. */
public final class CreatureTextureSmoke {
 private static final ObjectMapper JSON=new ObjectMapper();
 public static CompletableFuture<Map<String,Object>> prepare(ServerPlayer p,UUID agent){
  if(!Boolean.getBoolean("mineagent.skillSmoke")||!System.getProperty("mineagent.skillSmokeMode","").equals("event_abilities"))throw new IllegalStateException("SMOKE_DISABLED");var server=p.level().getServer();UUID owner=p.getUUID();
  return ServerBuildingFiles.library(p,agent).thenApplyAsync(library->{try{var image=new java.awt.image.BufferedImage(2,2,java.awt.image.BufferedImage.TYPE_INT_ARGB);image.setRGB(0,0,0xffff0000);image.setRGB(1,0,0xff00ff00);image.setRGB(0,1,0xff0000ff);image.setRGB(1,1,0xffffffff);var bytes=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"png",bytes);var png=bytes.toByteArray();UUID upload=library.begin(owner,"ability-fixture.png","FILE"),part=library.beginFile(owner,upload,"ability-fixture.png",png.length);library.chunk(owner,upload,part,0,png);return library.finish(owner,upload,"FIXTURE_ONLY").id();}catch(Exception e){throw new CompletionException(e);}})
  .thenCompose(file->server.submit(()->{try{String mesh=JSON.writeValueAsString(Map.of("version",1,"boxes",List.of(Map.of("from",List.of(-.5,0,-.5),"to",List.of(.5,1,.5),"color",List.of(255,255,255))),"collision",List.of(-.5,0,-.5,.5,1,.5),"texture","textures/test.png"));String source=JSON.writeValueAsString(Map.of("name","PNG native fixture","model",JSON.readTree(mesh),"bones",List.of(Map.of("name","body","pivot",List.of(0,0,0),"model",JSON.readTree(mesh)))));var args=JSON.createObjectNode().put("source",source);args.putObject("textures").put("textures/test.png",file.toString());return ConversationAgentTools.execute(p,agent,UUID.randomUUID(),"define_creature",args.toString(),()->true);}catch(Exception e){throw new CompletionException(e);}}).thenCompose(f->f))
  .thenCompose(receipt->server.submit(()->{try{if(!"APPLIED".equals(receipt.get("status")))throw new IllegalStateException("TEXTURE_DEFINE_"+receipt);var species=JSON.valueToTree(receipt).path("species");var id=UUID.fromString(species.path("id").asText());var def=RuntimeCreatures.get(server).get(owner,id).orElseThrow().definition();if(def.modelAssets().size()!=2)throw new IllegalStateException("TEXTURE_BONES_NOT_BOUND");var entity=new RuntimeCreatureEntity(dev.mineagent.runtime.neoforge.MineAgentRegistries.RUNTIME_CREATURE.get(),p.level());entity.bind(RuntimeCreatures.get(server).get(owner,id).orElseThrow(),true);entity.setNoAi(true);entity.setPos(p.getX(),p.getY(),p.getZ()+5);p.level().addFreshEntity(entity);p.teleportTo(p.level(),p.getX(),p.getY(),p.getZ(),Set.of(),0,8,true);return Map.<String,Object>of("entity",entity.getUUID().toString(),"species",id.toString(),"assets",def.modelAssets(),"rootAndBone",true);}catch(Exception e){throw new CompletionException(e);}}));
 }
 private CreatureTextureSmoke(){}
}
